select
,bcc.business_name
from movement_data mt left join `order` o ON mt.client_unique_id = o.id
LEFT JOIN shop bcc ON o.merchant_id = bcc.id

    and mt.id = #{id}
    and mt.multi_client = #{multiClient}
    and mt.client_name like concat('%', #{clientName},
        '%')

    and mt.acquirer_bank = #{acquirerBank}
    and mt.movement_date = #{movementDate}
    and mt.movement_type = #{movementType}
    and mt.movement_details = #{movementDetails}

    and mt.payment_method = #{paymentMethod}
    and mt.is_3d = #{is3d}
    and mt.card_type = #{cardType}
    and mt.country = #{country}
    and mt.transaction_result =
        #{transactionResult}

    and mt.transaction_id = #{transactionId}
    and mt.credit_card_last_4_digits =
        #{creditCardLast4Digits}

    and mt.client_unique_id = #{clientUniqueId}
    and mt.currency = #{currency}
    and mt.amount = #{amount}
    and mt.discount_fee = #{discountFee}
    and mt.transaction_fee = #{transactionFee}
    and mt.service_fee = #{serviceFee}
    and mt.reserve = #{reserve}
    and mt.vat_on_fees = #{vatOnFees}
    and mt.net_amount = #{netAmount}
    and mt.settlement_currency =
        #{settlementCurrency}

    and mt.settlement_amount = #{settlementAmount}
    and mt.settlement_reserve = #{settlementReserve}
    and mt.jurisdiction = #{jurisdiction}
    and mt.prepaid = #{prepaid}
    and mt.plus_commission = #{plusCommission}
    and mt.external_token_provider =
        #{externalTokenProvider}

    and mt.on_us = #{onUs}
    and mt.order_id = #{orderId}
    and mt.is_interchange_plus_plus =
        #{isInterchangePlusPlus}

    and mt.reseller_fee = #{resellerFee}
    and mt.is_online_payout = #{isOnlinePayout}
    and mt.movement_id = #{movementId}
    and mt.scheme_fee = #{schemeFee}
    and mt.reseller_commission = #{resellerCommission}
    and mt.interchange_fee = #{interchangeFee}
    and mt.site_id = #{siteId}
    and mt.site_name like concat('%', #{siteName}, '%')
    and mt.card_product = #{cardProduct}
    and mt.custom_data = #{customData}
    and mt.arn = #{arn}
    and mt.payout_id = #{payoutId}
    and mt.bank_transaction_id =
        #{bankTransactionId}

    and mt.is_aft = #{isAft}
    and mt.batch_id = #{batchId}
    and mt.processing_channel =
        #{processingChannel}

    and mt.bin = #{bin}
    and mt.record_id = #{recordId}
    and mt.is_currency_converted =
        #{isCurrencyConverted}

    and mt.payment_sub_method =
        #{paymentSubMethod}

    and mt.end_user_amount = #{endUserAmount}
    and mt.end_user_currency =
        #{endUserCurrency}

    and mt.movement_import_id = #{movementImportId}

order by mt.id

