multi_client = #{multiClient}, client_name = #{clientName}, acquirer_bank = #{acquirerBank}, movement_date = #{movementDate}, movement_type = #{movementType}, movement_details = #{movementDetails}, payment_method = #{paymentMethod}, is_3d = #{is3d}, card_type = #{cardType}, country = #{country}, transaction_result = #{transactionResult}, transaction_id = #{transactionId}, credit_card_last_4_digits = #{creditCardLast4Digits}, client_unique_id = #{clientUniqueId}, currency = #{currency}, amount = #{amount}, discount_fee = #{discountFee}, transaction_fee = #{transactionFee}, service_fee = #{serviceFee}, reserve = #{reserve}, vat_on_fees = #{vatOnFees}, net_amount = #{netAmount}, settlement_currency = #{settlementCurrency}, settlement_amount = #{settlementAmount}, settlement_reserve = #{settlementReserve}, jurisdiction = #{jurisdiction}, prepaid = #{prepaid}, plus_commission = #{plusCommission}, external_token_provider = #{externalTokenProvider}, on_us = #{onUs}, order_id = #{orderId}, is_interchange_plus_plus = #{isInterchangePlusPlus}, reseller_fee = #{resellerFee}, is_online_payout = #{isOnlinePayout}, movement_id = #{movementId}, scheme_fee = #{schemeFee}, reseller_commission = #{resellerCommission}, interchange_fee = #{interchangeFee}, site_id = #{siteId}, site_name = #{siteName}, card_product = #{cardProduct}, custom_data = #{customData}, arn = #{arn}, payout_id = #{payoutId}, bank_transaction_id = #{bankTransactionId}, is_aft = #{isAft}, batch_id = #{batchId}, processing_channel = #{processingChannel}, bin = #{bin}, record_id = #{recordId}, is_currency_converted = #{isCurrencyConverted}, payment_sub_method = #{paymentSubMethod}, end_user_amount = #{endUserAmount}, end_user_currency = #{endUserCurrency}, movement_import_id = #{movementImportId}, merchant_processing_fee = #{merchantProcessingFee}, merchant_rolling_reserve = #{merchantRollingReserve}, merchant_gateway_fee = #{merchantGatewayFee}, merchant_refund_fee = #{merchantRefundFee}, merchant_rdr_fee = #{merchantRdrFee}, merchant_chargeback_fee = #{merchantChargebackFee}, merchant_settlement_fee = #{merchantSettlementFee}, merchant_settlement_remark = #{merchantSettlementRemark},
