mapper.select:
SELECT GROUP_CONCAT(DISTINCT month SEPARATOR '--') AS combined_months FROM ( SELECT DATE_FORMAT(MAX(movement_date), '%Y.%m') AS month FROM movement_data WHERE movement_import_id IN
#{movementImportId}
GROUP BY movement_import_id ORDER BY movement_import_id ) AS subquery

SELECT DATE(max(movement_date)) day from movement_data WHERE movement_import_id in

    #{movementImportId}

GROUP BY movement_import_id ORDER BY movement_import_id

SELECT movement_import_id,i.b2c2_fx_rate,DATE(max(movement_date)) day from movement_data d LEFT JOIN movement_import i on d.movement_import_id = i.id WHERE movement_import_id in
#{movementImportId}
GROUP BY movement_import_id ORDER BY day

SELECT b.business_name, movement_import_id, DATE(max(movement_date)) AS DAY, ANY_VALUE(payout_id) AS payout_id, ROUND(ANY_VALUE(fx_rate), 2) AS fx_rate, CASE WHEN SUM(merchant_settlement_fee) >= 0 THEN TRUNCATE(SUM(merchant_settlement_fee), 2) ELSE -ROUND(CEIL(ABS(SUM(merchant_settlement_fee)) * 100) / 100, 2) END AS settlement, ROUND(SUM(IF(currency = 'USD', amount, 0)), 2) AS order_amount_usd, ROUND(SUM(IF(currency = 'EUR', amount, 0)), 2) AS order_amount_eur, ROUND(SUM(merchant_rolling_reserve), 2) AS rolling_reserve_usd, ROUND(SUM(IF(movement_type = 'Sales', settlement_amount / net_amount * amount, 0)), 2) AS rolling_reserve, ROUND( SUM( IF (movement_type = 'Chargeback', ABS(transfer_amount) + IFNULL(m.cb_fee, 0), 0) + IF (movement_type = 'Credits', ABS(transfer_amount) + IFNULL(m.refund_fee, 0), 0) ), 2 ) AS chargeback_refunds, ROUND( SUM( IF ( movement_type = 'Chargeback', ABS( settlement_amount ) * fx_rate,0) + IF ( movement_type = 'Credits', ABS( settlement_amount ) * fx_rate, 0 ) ), 2 ) AS nuvie_chargeback_refunds, ROUND(SUM(IFNULL(merchant_processing_fee, 0) + IFNULL(merchant_gateway_fee, 0)), 2) AS fees, ROUND(SUM(IFNULL(o.rolling_fee, 0)), 2) AS rolling_reserve_payout, ROUND(SUM(d.amount), 2) AS order_amount, ROUND(SUM(settlement_amount), 2) AS settlement_in_bank, ROUND( SUM( -( settlement_amount / net_amount * IFNULL(discount_fee, 0)) - ( settlement_amount / net_amount * IFNULL(transaction_fee, 0)) - ( settlement_amount / net_amount * amount ) + IF (movement_type = 'Sales', settlement_amount / net_amount * amount, 0) ), 2 ) AS nuvie_fees, ROUND(SUM(ABS(amount) * IFNULL(base_rate, 0) - ABS(IFNULL(transfer_amount, 0))), 2) AS fx_on_order_amounts FROM movement_data d LEFT JOIN `order` o ON d.client_unique_id = o.id LEFT JOIN shop b ON o.merchant_id = b.id LEFT JOIN merchant_fee_model m ON b.merchant_fee_model_id = m.id WHERE movement_import_id in
#{movementImportId}
GROUP BY o.merchant_id, movement_import_id ORDER BY o.merchant_id, movement_import_id

SELECT DATE(MAX(movement_date)) AS last_day
FROM movement_data
WHERE movement_import_id = #{movementImportId}

SELECT d.*, o.merchant_id,o.rolling_fee, b.business_name, m.cb_fee,i.b2c2_fx_rate, m.refund_fee FROM movement_data d LEFT JOIN `order` o ON d.client_unique_id = o.id LEFT JOIN shop b ON o.merchant_id = b.id LEFT JOIN merchant_fee_model m ON b.merchant_fee_model_id = m.id left join movement_import i on d.movement_import_id = i.id WHERE d.movement_import_id IN
#{id}
and d.client_unique_id is not null

SELECT
DATE(d.movement_date) as date,d.movement_type as type,
COUNT(distinct d.client_unique_id) as count
FROM movement_data d left join `order` o on d.client_unique_id = o.id
WHERE d.movement_date >= #{startDate}
AND d.movement_date <= #{endDate}

    AND d.movement_type in

        #{item}



    AND o.merchant_id = #{shopId}

GROUP BY DATE(d.movement_date)
ORDER BY date

SELECT
DATE(d.movement_date) as date,d.movement_type as type,
SUM(abs(d.transfer_amount)) as amount
FROM movement_data d left join `order` o on d.client_unique_id = o.id
WHERE d.movement_date >= #{startDate}
AND d.movement_date <= #{endDate}

    AND d.movement_type in

        #{item}



    AND o.merchant_id = #{shopId}

GROUP BY DATE(d.movement_date)
ORDER BY date

SELECT
COUNT(distinct d.client_unique_id)
FROM movement_data d left join `order` o on d.client_unique_id = o.id
WHERE d.movement_date >= #{startDate}
AND d.movement_date <= #{endDate}
AND d.movement_type = #{movementType}

    AND o.merchant_id = #{shopId}
